//! `GeneratedShape`: what a shape generated on another (glued, or swept) tells
//! the generator: its generating edges, the edge generated by a vertex, the face
//! generated by an edge, and its oriented faces. `GluedShape` answers it for a
//! shape glued on faces.
use crate::errors::{construction_error, no_such_object};
use martensite_tkbrep::topexp::{self, Explorer};
use martensite_tkbrep::topods::{self, Edge, Face, Shape, Vertex};
use martensite_tkbrep::toptools::{IndexedDataMapOfShapeListOfShape, MapOfShape, ShapeMapHasher};
use martensite_tkernel::ncollection::{DataMap, List};
use martensite_tkernel::standard::{Failure, StandardTransient, Transient};
use martensite_tkg3d::top_abs::ShapeEnum;

/// `GeneratedShape`: the virtual members of a generated shape. The
/// implementations compute their maps on first use, hence `&mut self`.
/// Custom implementors retain an owned transient base, as does `GluedShape`.
/// Example: `let generated: &dyn GeneratedShape = &GluedShape::default();`.
pub trait GeneratedShape: Transient {
    /// The edges of the basis the shape is generated from.
    fn generating_edges(&mut self) -> Result<&List<Shape>, Failure>;

    /// The edge generated by the vertex `v` (null when none).
    fn generated_by_vertex(&mut self, v: &Vertex) -> Result<Edge, Failure>;

    /// The face generated by the edge `e` (null when none).
    fn generated_by_edge(&mut self, e: &Edge) -> Result<Face, Failure>;

    /// The correctly oriented generated faces.
    fn oriented_faces(&mut self) -> Result<&List<Shape>, Failure>;
}

martensite_tkernel::impl_transient_interface!(
    dyn GeneratedShape,
    "LocOpe_GeneratedShape",
    StandardTransient
);

/// `GluedShape`: a shape glued on faces of a basis; its generating edges are the
/// edges between a glued face and a free one.
///
/// ```
/// use martensite_tkfeat::loc_ope::GluedShape;
/// use martensite_tkbrep::topods::Shape;
/// let glued = GluedShape::new(&Shape::default());
/// # let _ = glued;
/// ```
#[derive(Default)]
pub struct GluedShape {
    // Keep the reference base's counter operation-local; cloning resets its ownership count.
    transient: StandardTransient,
    shape: Shape,
    map: MapOfShape,
    g_shape: DataMap<Shape, Shape, ShapeMapHasher>,
    g_edges: List<Shape>,
    list: List<Shape>,
}

impl Clone for GluedShape {
    /// Copy state into a fresh zero-counter owner; `let copied = glued.clone()`.
    fn clone(&self) -> Self {
        Self {
            transient: self.transient.clone(),
            shape: self.shape.clone(),
            map: self.map.clone(),
            g_shape: self.g_shape.clone(),
            g_edges: self.g_edges.clone(),
            list: self.list.clone(),
        }
    }

    /// Preserve the target counter during assignment; `target.clone_from(&source)`.
    fn clone_from(&mut self, source: &Self) {
        // f452af042 exposed counters: reference StandardTransient assignment preserves them.
        self.transient.clone_from(&source.transient);
        self.shape.clone_from(&source.shape);
        self.map.clone_from(&source.map);
        self.g_shape.clone_from(&source.g_shape);
        self.g_edges.clone_from(&source.g_edges);
        self.list.clone_from(&source.list);
    }
}

martensite_tkernel::impl_transient!(
    GluedShape,
    "LocOpe_GluedShape",
    dyn GeneratedShape,
    transient,
    interfaces: [dyn GeneratedShape]
);

impl GluedShape {
    /// `glued_shape(S)`; `GluedShape::new(&s)`.
    pub fn new(s: &Shape) -> Self {
        Self {
            shape: s.clone(),
            ..Self::default()
        }
    }

    /// A new shape, every map cleared; `glued.init(&s)`.
    pub fn init(&mut self, s: &Shape) {
        self.shape = s.clone();
        self.map.clear(false);
        self.g_shape.clear(false);
        self.list.clear();
        self.g_edges.clear();
    }

    /// The face `f` of the shape (with its orientation in it) is glued;
    /// construction_error when it is not a face of the shape;
    /// `glued.glue_on_face(&f)?`.
    pub fn glue_on_face(&mut self, f: &Face) -> Result<(), Failure> {
        let found = Explorer::new(&self.shape, ShapeEnum::Face, ShapeEnum::Shape)?
            .find(|x| x.is_same(f))
            .ok_or_else(|| {
                construction_error(
                    "LocOpe_GluedShape::GlueOnFace",
                    "the face is not in the glued shape",
                )
            })?;
        self.map.add(found); // bonne orientation
        Ok(())
    }

    /// The edges between a glued face and a free one (generating, reversed) and the free
    /// face of each; construction_error for a glued edge without two faces.
    fn map_generating_edges(
        &mut self,
        the_map_ef: &IndexedDataMapOfShapeListOfShape,
    ) -> Result<(), Failure> {
        let mut mapdone = MapOfShape::default();
        let glued: Vec<Shape> = self.map.iter().cloned().collect();
        for fac in &glued {
            for edg in Explorer::new(fac, ShapeEnum::Edge, ShapeEnum::Shape)? {
                if mapdone.contains(&edg) {
                    continue;
                }
                // Est-ce un edge de connexite entre les faces collees
                let faces = the_map_ef.find_from_key(&edg)?;
                if faces.len() != 2 {
                    return Err(construction_error(
                        "LocOpe_GluedShape::MapEdgeAndVertices",
                        "an edge of a glued face is not shared by two faces",
                    ));
                }
                if let Some(free) = faces.iter().find(|x| !self.map.contains(x)) {
                    //	g_edges.Append(edg);
                    self.g_edges.append(edg.reversed());
                    self.g_shape.bind(edg.clone(), free.clone()); // voir orientation, mais devrait etre bon
                }
                mapdone.add(edg);
            }
        }
        Ok(())
    }

    /// The edge of the face generated by `edg` (other than `edg`) through the vertex
    /// `vtx`: null when that edge is itself generating.
    fn edge_at_vertex(&self, edg: &Shape, vtx: &Shape) -> Result<Option<Shape>, Failure> {
        let face = self.g_shape.find(edg)?;
        for e2 in Explorer::new(face, ShapeEnum::Edge, ShapeEnum::Shape)? {
            if e2.is_same(edg) {
                continue;
            }
            let mut vertices = Explorer::new(&e2, ShapeEnum::Vertex, ShapeEnum::Shape)?;
            if vertices.any(|x| x.is_same(vtx)) {
                if self.g_shape.is_bound(&e2) {
                    return Ok(Some(Shape::default()));
                }
                return Ok(Some(e2));
            }
        }
        Ok(None)
    }

    /// Once, the generating edges, the faces and edges they
    /// generate, and the free faces.
    fn map_edge_and_vertices(&mut self) -> Result<(), Failure> {
        if !self.g_shape.is_empty() {
            return Ok(());
        }
        // Edges et faces generes
        let mut the_map_ef = IndexedDataMapOfShapeListOfShape::default();
        topexp::map_shapes_and_ancestors(
            &self.shape,
            ShapeEnum::Edge,
            ShapeEnum::Face,
            &mut the_map_ef,
        )?;
        self.map_generating_edges(&the_map_ef)?;
        let g_edges: Vec<Shape> = self.g_edges.iter().cloned().collect();
        for edg in &g_edges {
            for vtx in Explorer::new(edg, ShapeEnum::Vertex, ShapeEnum::Shape)? {
                if self.g_shape.is_bound(&vtx) {
                    continue;
                }
                if let Some(generated) = self.edge_at_vertex(edg, &vtx)? {
                    self.g_shape.bind(vtx, generated);
                }
            }
        }
        // liste de faces
        for f in Explorer::new(&self.shape, ShapeEnum::Face, ShapeEnum::Shape)? {
            if !self.map.contains(&f) {
                self.list.append(f);
            }
        }
        Ok(())
    }

    fn generated(&mut self, s: &Shape) -> Result<&Shape, Failure> {
        if self.g_shape.is_empty() {
            self.map_edge_and_vertices()?;
        }
        self.g_shape.seek(s).ok_or_else(|| {
            no_such_object(
                "LocOpe_GluedShape::Generated",
                "the shape generates nothing",
            )
        })
    }
}

impl GeneratedShape for GluedShape {
    fn generating_edges(&mut self) -> Result<&List<Shape>, Failure> {
        if self.g_shape.is_empty() {
            self.map_edge_and_vertices()?;
        }
        Ok(&self.g_edges)
    }

    fn generated_by_vertex(&mut self, v: &Vertex) -> Result<Edge, Failure> {
        topods::edge(self.generated(v)?)
    }

    fn generated_by_edge(&mut self, e: &Edge) -> Result<Face, Failure> {
        topods::face(self.generated(e)?)
    }

    fn oriented_faces(&mut self) -> Result<&List<Shape>, Failure> {
        if self.g_shape.is_empty() {
            self.map_edge_and_vertices()?;
        }
        Ok(&self.list)
    }
}
